        private bool MemberFieldPredicate(System.Reflection.FieldInfo field)
        {
            return (field.IsPublic 
                    && (field.IsStatic 
                        && (field.GetValue(null) is DataStandardizer.ISO639.Iso639Part1Language memberValue 
                            && (memberValue._value == this._value))));
        }
        #endregion
    }
}